from pathlib import Path

s=Path('preview-v85.html').read_text(encoding='utf-8')
s=s.replace('<title>GTVI 26 Weather App · Mobile v85 Preview</title>','<title>GTVI 26 Weather App · Mobile v86 Preview</title>',1)

old='''function bundleSummaryPoint(b,s){const rs=b.forecasts.filter(Boolean),disp=rs[0]||b.best;if(!disp)return null;const rains=rs.map(x=>x.rain).filter(Number.isFinite),precip=rs.map(x=>x.precip).filter(Number.isFinite),gusts=rs.map(x=>x.gust).filter(Number.isFinite),temps=rs.map(x=>x.temp).filter(Number.isFinite);const rainProb=Number.isFinite(b.best?.rain)?b.best.rain:(rains.length?Math.max(...rains):null);const meanPrecip=precip.length?precip.reduce((a,c)=>a+c,0)/precip.length:(Number.isFinite(disp.precip)?disp.precip:0);const gust=gusts.length?gusts.reduce((a,c)=>a+c,0)/gusts.length:(Number.isFinite(disp.gust)?disp.gust:0);const temp=temps.length?temps.reduce((a,c)=>a+c,0)/temps.length:(Number.isFinite(disp.temp)?disp.temp:null);const clouds=rs.map(x=>x.cloud).filter(Number.isFinite);const cloud=clouds.length?clouds.reduce((a,c)=>a+c,0)/clouds.length:(Number.isFinite(disp.cloud)?disp.cloud:null);const a=pointArrivalMinutes(b.p,s);return {km:b.p.km,time:a.time,rainProb,precip:meanPrecip,gust,temp,cloud}}'''
new='''function meanFinite(v){v=v.filter(Number.isFinite);return v.length?v.reduce((a,c)=>a+c,0)/v.length:null}\nfunction consensusRainProbability(b,s,idx){\n const probs=b.forecasts.filter(Boolean).map(x=>x.rain).filter(Number.isFinite);\n const ep=pointEnsembleRainProbability(ensembleCache[s.key],s,b.p,idx);\n if(Number.isFinite(ep))probs.push(ep);\n if(probs.length)return meanFinite(probs);\n return Number.isFinite(b.best?.rain)?b.best.rain:null;\n}\nfunction bundleSummaryPoint(b,s,idx=0){const rs=b.forecasts.filter(Boolean),disp=rs[0]||b.best;if(!disp)return null;const precip=rs.map(x=>x.precip).filter(Number.isFinite),gusts=rs.map(x=>x.gust).filter(Number.isFinite),winds=rs.map(x=>x.wind).filter(Number.isFinite),temps=rs.map(x=>x.temp).filter(Number.isFinite),windDirs=rs.map(x=>x.wdir).filter(Number.isFinite);const rainProb=consensusRainProbability(b,s,idx);const meanPrecip=meanFinite(precip)??(Number.isFinite(disp.precip)?disp.precip:0);const gust=meanFinite(gusts)??(Number.isFinite(disp.gust)?disp.gust:0);const wind=meanFinite(winds)??(Number.isFinite(disp.wind)?disp.wind:0);const temp=meanFinite(temps)??(Number.isFinite(disp.temp)?disp.temp:null);const cloud=meanFinite(rs.map(x=>x.cloud))??(Number.isFinite(disp.cloud)?disp.cloud:null);const wdir=circularMeanDeg(windDirs);const a=pointArrivalMinutes(b.p,s);return {km:b.p.km,time:a.time,rainProb,precip:meanPrecip,gust,wind,temp,cloud,wdir}}'''
if old not in s: raise SystemExit('bundleSummaryPoint anchor not found')
s=s.replace(old,new,1)

s=s.replace('bundles.map(b=>bundleSummaryPoint(b,s)).filter(Boolean)','bundles.map((b,idx)=>bundleSummaryPoint(b,s,idx)).filter(Boolean)')

old='''function summarize(bundles){\n const all=bundles.flatMap(b=>b.forecasts.filter(Boolean));\n if(!all.length)return null;\n const temps=all.map(r=>r.temp).filter(Number.isFinite), gusts=all.map(r=>r.gust).filter(Number.isFinite);\n const rainProbs=bundles.map(b=>b.best?.rain).filter(Number.isFinite);\n const wetFrac=all.filter(wet).length/all.length;\n const thunder=all.some(r=>r.code>=95), heavy=all.some(r=>(r.precip??0)>=2.5);\n const confs=bundles.map(b=>b.conf.level);\n const overall=confs.includes("low")?"low":confs.includes("medium")?"medium":"high";\n let phrase=thunder?"Thunderstorm risk":heavy?"Periods of rain likely":wetFrac>.55?"Showery / wet":wetFrac>.2?"Some shower risk":"Mostly dry";\n const tmin=Math.round(Math.min(...temps)),tmax=Math.round(Math.max(...temps));\n const gmax=Math.round(Math.max(...gusts));\n const rp=rainProbs.length?Math.round(Math.max(...rainProbs)):null;\n const sky=skySummary(bundles);\n return {phrase,tmin,tmax,gmax,rp,overall,sky};\n}'''
new='''function summarize(bundles,s=stage()){\n const pts=bundles.map((b,idx)=>bundleSummaryPoint(b,s,idx)).filter(Boolean);\n if(!pts.length)return null;\n const temps=pts.map(p=>p.temp).filter(Number.isFinite),gusts=pts.map(p=>p.gust).filter(Number.isFinite),rainProbs=pts.map(p=>p.rainProb).filter(Number.isFinite);\n const pointVotes=bundles.map(b=>{const rs=b.forecasts.filter(Boolean),need=Math.max(1,Math.ceil(rs.length/2));return {wet:rs.filter(wet).length>=need,thunder:rs.filter(r=>r.code>=95).length>=need}});\n const wetFrac=pointVotes.length?pointVotes.filter(x=>x.wet).length/pointVotes.length:0;\n const thunder=pointVotes.some(x=>x.thunder),heavy=pts.some(p=>(p.precip??0)>=2.5);\n const confs=bundles.map(b=>b.conf.level);\n const overall=confs.includes("low")?"low":confs.includes("medium")?"medium":"high";\n let phrase=thunder?"Thunderstorm risk":heavy?"Periods of rain likely":wetFrac>.55?"Showery / wet":wetFrac>.2?"Some shower risk":"Mostly dry";\n const tmin=temps.length?Math.round(Math.min(...temps)):null,tmax=temps.length?Math.round(Math.max(...temps)):null;\n const gmax=gusts.length?Math.round(Math.max(...gusts)):null;\n const rp=rainProbs.length?Math.round(Math.max(...rainProbs)):null;\n const sky=skySummary(bundles);\n return {phrase,tmin,tmax,gmax,rp,overall,sky};\n}'''
if old not in s: raise SystemExit('summarize anchor not found')
s=s.replace(old,new,1)
s=s.replace('const sm=summarize(bundles);','const sm=summarize(bundles,s);',1)
s=s.replace('const consensusSm=summarize(consensusBundles);','const consensusSm=summarize(consensusBundles,s);',1)

start=s.find('function renderTimelineFromBundles(bundles,s){')
end=s.find('function renderDeterministicResults(',start)
if start<0 or end<0: raise SystemExit('timeline block not found')
new_timeline='''function renderTimelineFromBundles(bundles,s){\n const stillLoading=anyDeterministicPending(s);const currentIdx=currentRoutePointIndex(bundles,s);\n document.getElementById("timeline").innerHTML=bundles.map((b,idx)=>{const rs=b.forecasts.filter(Boolean),disp=rs[0]||b.best;const activeClass=idx===currentIdx?" currentRoutePoint":"",badge=idx===currentIdx?`<span class="routePointBadge">NEXT</span>`:"";if(!disp){const status=stillLoading?"Loading forecast…":"Forecast not yet in range";return `<div class="stop${activeClass}"><div class="stopPlace">${b.p.label==="Start"?s.start:b.p.label==="Finish"?s.finish:b.p.label}${badge}</div><div class="stopMeta">${b.p.km} km · ${b.p.ele} m · ~${rideClock(b.p.ride_h,s,b.p.km)}</div><div class="risk">${status}</div></div>`}\n const cp=bundleSummaryPoint(b,s,idx),meanT=Math.round(cp.temp),wind=Math.round(cp.wind),gust=Math.round(cp.gust),prob=cp.rainProb,meanWindDir=cp.wdir,routeBearing=routeBearingAtKm(s,b.p.km),windEffect=windEffectLabel(routeBearing,meanWindDir,wind);\n const wetN=rs.filter(wet).length,need=Math.max(1,Math.ceil(rs.length/2)),thunderN=rs.filter(x=>x.code>=95).length,thunder=thunderN>=need,wetConsensus=wetN>=need;\n const code=thunder?95:wetConsensus?80:wetN>0?80:disp.code,cond=thunder?"Thunder":wetConsensus?"Rain/showers":wetN>0?"Possible shower":WDESC[code]||"Dry",cclass=thunder?"danger":wetConsensus?"rainWet":"";\n const detail=MODELS.map(md=>{const r=b.forecasts.find(x=>x&&x.source.id===md.id);if(r){let rainProb=Number.isFinite(r.rain)?Math.round(r.rain)+"%":"—";if(md.id==="ecmwf"&&!Number.isFinite(r.rain)){const ep=pointEnsembleRainProbability(ensembleCache[s.key],s,b.p,idx);if(Number.isFinite(ep))rainProb=ep+"% ENS";}return `<div class="modelRow"><b>${md.label}</b><span>${Math.round(r.temp)}°</span><span>Rain ${r.precip.toFixed(1)} mm/h · ${rainProb}</span><span>${Math.round(r.wind)} / ${Math.round(r.gust)} km/h</span></div>`;}if(isResultPending(s,md.id))return `<div class="modelRow"><b>${md.label}</b><span>…</span><span>loading…</span><span>…</span></div>`;return `<div class="modelRow"><b>${md.label}</b><span>—</span><span>not in range</span><span>—</span></div>`}).join("");\n return `<div class="stop${activeClass}"><div class="stopMain"><div><div class="stopPlace"><span class="stopName">${b.p.label==="Start"?s.start:b.p.label==="Finish"?s.finish:b.p.label}</span>${badge}</div><div class="stopMeta">${b.p.km} km · ${b.p.ele} m · ~${rideClock(b.p.ride_h,s,b.p.km)}</div></div><div class="pointWeather"><div class="pointCondition"><div class="wxIcon" aria-hidden="true">${WICON(code)}</div><div class="conditionText">${cond}</div></div><div class="pointMetrics"><div class="pointMetricRow"><span class="pointMetricLabel">Temp</span><span class="pointMetricValue">${meanT}°</span></div><div class="pointMetricRow"><span class="pointMetricLabel">Rain</span><span class="pointMetricValue ${cclass}">${prob==null?"—":Math.round(prob)+"%"}</span></div><div class="pointMetricRow"><span class="pointMetricLabel">Wind</span><span class="pointMetricValue">${wind} km/h</span></div><div class="pointGust">gust ${gust} km/h</div>${windEffect?`<div class="pointGust pointWindEffect">${windEffect.label}</div>`:""}</div></div></div><details><summary>${b.conf.label.replace(" forecast consensus"," consensus")} · show detail</summary><div class="modelGrid">${detail}</div></details></div>`}).join("");renderWorstHighlights(bundles,s);\n}\n'''
s=s[:start]+new_timeline+s[end:]

old='''   card("Windiest",windiest,`gust ${Math.round(windiest?.gust)} km/h`)'''
new='''   card("Windiest",windiest,`${Math.round(windiest?.wind)} km/h · gust ${Math.round(windiest?.gust)} km/h`)'''
if old not in s: raise SystemExit('windiest anchor not found')
s=s.replace(old,new,1)

s=s.replace('document.getElementById("mWind").textContent=w+" km/h";','document.getElementById("mWind").textContent=`Peak ~${w} km/h`;')
s=s.replace('document.getElementById("mWindSub").textContent=`gusts ~${g} km/h${risk.p60>0?` · 60+ risk ${risk.p60}%`:""}`;','document.getElementById("mWindSub").textContent=`peak gust ~${g} km/h${risk.p60>0?` · 60+ risk ${risk.p60}%`:""}`;')
s=s.replace('document.getElementById("mRainSub").textContent=risk.rainHeavy?`heavier rain ${risk.rainHeavy}%`:"mostly light/no rain signal";','document.getElementById("mRainSub").textContent=risk.rainHeavy?`somewhere on ride · heavier rain ${risk.rainHeavy}%`:"chance somewhere on ride";')
s=s.replace('document.getElementById("mRainSub").textContent="forecast probability";','document.getElementById("mRainSub").textContent="highest route-point consensus";')

about_old='<li><b>Weather along the way</b> is matched to your expected position on the route based on the start time, riding speed and planned stops entered in the RIDE PLAN above.</li>'
about_new=about_old+'\n      <li><b>Along-the-way headline values</b> use the consensus of ECMWF, DWD ICON and GFS at that route point; individual model values remain under show detail. Rain probability also uses ECMWF ensemble probability where available.</li>'
if about_old not in s: raise SystemExit('about anchor not found')
s=s.replace(about_old,about_new,1)

Path('preview-v86.html').write_text(s,encoding='utf-8')
print('built preview-v86.html')
